/**
 * Returns the SVG markup for the given ISO language or country code.
 * Falls back to globe icon or null if no flag found.
 */
export function getFlagSvg(langOrCountry: string | null | undefined): string | null {
  if (!langOrCountry) return null
  const code = langOrCountry.toLowerCase().trim()
  if (COUNTRY_FLAGS[code]) return COUNTRY_FLAGS[code]
  const country = LANG_TO_COUNTRY[code] || LANG_TO_COUNTRY[code.split('-')[0]] || LANG_TO_COUNTRY[code.split('_')[0]]
  if (country && COUNTRY_FLAGS[country]) return COUNTRY_FLAGS[country]
  return COUNTRY_FLAGS.globe || null
}

export const getLanguageFlag = getFlagSvg
